{"content":"const fs = require('fs');

function fail(msg) {
  console.error(`Error: ${msg}`);
  process.exit(1);
}

function readVarInt(buf, offset) {
  if (offset >= buf.length) fail('unexpected end of data while reading varint');
  const first = buf[offset];
  if (first < 0xfd) {
    return { value: first, size: 1 };
  } else if (first === 0xfd) {
    if (offset + 3 > buf.length) fail('unexpected end of data while reading varint (0xfd)');
    const value = buf.readUInt16LE(offset + 1);
    return { value, size: 3 };
  } else if (first === 0xfe) {
    if (offset + 5 > buf.length) fail('unexpected end of data while reading varint (0xfe)');
    const value = buf.readUInt32LE(offset + 1);
    return { value, size: 5 };
  } else {
    // 0xff
    if (offset + 9 > buf.length) fail('unexpected end of data while reading varint (0xff)');
    const big = buf.readBigUInt64LE(offset + 1);
    if (big > BigInt(Number.MAX_SAFE_INTEGER)) {
      fail('varint value exceeds maximum safe integer');
    }
    return { value: Number(big), size: 9 };
  }
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    fail('missing file path argument. Usage: node parse_tx.js <path_to_hex_file>');
  }

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    fail(`cannot read file: ${e.message}`);
  }

  // Strip whitespace (spaces, newlines, tabs, etc.)
  const hex = raw.replace(/\s+/g, '');

  if (hex.length === 0) {
    fail('empty hex string');
  }
  if (hex.length % 2 !== 0) {
    fail('malformed hex string: odd length');
  }
  if (!/^[0-9a-fA-F]*$/.test(hex)) {
    fail('malformed hex string: contains non-hex characters');
  }

  let buf;
  try {
    buf = Buffer.from(hex, 'hex');
  } catch (e) {
    fail(`malformed hex string: ${e.message}`);
  }

  if (buf.length === 0) {
    fail('empty transaction data');
  }

  let offset = 0;

  function need(n, what) {
    if (offset + n > buf.length) {
      fail(`unexpected end of data while reading ${what}`);
    }
  }

  // Version (4 bytes LE)
  need(4, 'version');
  const version = buf.readUInt32LE(offset);
  offset += 4;

  // Input count (VarInt)
  const ic = readVarInt(buf, offset);
  offset += ic.size;
  const inputCount = ic.value;

  const inputs = [];
  for (let i = 0; i < inputCount; i++) {
    // txid (32 bytes, reversed for display)
    need(32, `input ${i} txid`);
    const txid = Buffer.from(buf.subarray(offset, offset + 32)).reverse().toString('hex');
    offset += 32;

    // vout (4 bytes LE)
    need(4, `input ${i} vout`);
    const vout = buf.readUInt32LE(offset);
    offset += 4;

    // scriptsig length (VarInt)
    const sl = readVarInt(buf, offset);
    offset += sl.size;

    // scriptsig
    need(sl.value, `input ${i} scriptsig`);
    const scriptsig = buf.subarray(offset, offset + sl.value).toString('hex');
    offset += sl.value;

    // sequence (4 bytes LE)
    need(4, `input ${i} sequence`);
    const sequence = buf.readUInt32LE(offset);
    offset += 4;

    inputs.push({ txid, vout, scriptsig, sequence });
  }

  // Output count (VarInt)
  if (offset >= buf.length) fail('unexpected end of data while reading output count');
  const oc = readVarInt(buf, offset);
  offset += oc.size;
  const outputCount = oc.value;

  const outputs = [];
  for (let i = 0; i < outputCount; i++) {
    // value (8 bytes LE)
    need(8, `output ${i} value`);
    const valueBig = buf.readBigUInt64LE(offset);
    offset += 8;
    // JSON cannot represent BigInt; convert to Number.
    // All realistic satoshi values are within safe integer range.
    const value = Number(valueBig);

    // scriptpubkey length (VarInt)
    if (offset >= buf.length) fail(`unexpected end of data while reading output ${i} scriptpubkey length`);
    const pl = readVarInt(buf, offset);
    offset += pl.size;

    // scriptpubkey
    need(pl.value, `output ${i} scriptpubkey`);
    const scriptpubkey = buf.subarray(offset, offset + pl.value).toString('hex');
    offset += pl.value;

    outputs.push({ value, scriptpubkey });
  }

  // Locktime (4 bytes LE)
  need(4, 'locktime');
  const locktime = buf.readUInt32LE(offset);
  offset += 4;

  if (offset !== buf.length) {
    fail(`malformed transaction: ${buf.length - offset} trailing byte(s) remaining`);
  }

  const result = {
    version,
    input_count: inputCount,
    inputs,
    output_count: outputCount,
    outputs,
    locktime,
  };

  process.stdout.write(JSON.stringify(result) + '\n');
}

main();
